using System.Drawing;using Rhino.Display;using Rhino.DocObjects;using Rhino.Geometry;
namespace RhinoContextAssist;
internal sealed class ContextAssistHudConduit:DisplayConduit{
 readonly HudState state;readonly ContextAssistSettings settings;internal ContextAssistHudConduit(HudState s,ContextAssistSettings x){state=s;settings=x;}
 protected override void DrawForeground(DrawEventArgs e){if(!settings.Enabled||state.Actions.Count==0)return;var size=e.Display.Viewport.Size;var actions=state.Actions.Take(settings.PrimaryCount).ToList();const int h=38;int x=PositionX(size.Width,actions);int y=PositionY(size.Height);state.Regions.Clear();var titleWidth=Measure(state.Context.Caption)+36;var totalWidth=titleWidth+actions.Sum(a=>Measure(a.Label)+34)+66;state.Bounds=new Rectangle(x,y,totalWidth,h);e.Display.Draw2dRectangle(state.Bounds,Color.FromArgb(120,255,255,255),1,Color.FromArgb(232,38,38,38));DrawText(e,$"{Icon(state.Context.Kind)} {state.Context.Caption}",x+12,y+12,Color.Gainsboro,11,true);x+=titleWidth;for(int i=0;i<actions.Count;i++){var a=actions[i];int w=Measure(a.Label)+34;var r=new Rectangle(x,y,w,h);var fill=i==state.HoverIndex?Color.FromArgb(90,255,255,255):Color.FromArgb(0,0,0,0);e.Display.Draw2dRectangle(r,Color.FromArgb(40,255,255,255),1,fill);DrawText(e,$"{(settings.Favorite(a.Id)?"★ ":"")}{a.Icon} {a.Label}",x+8,y+12,a.Destructive?Color.FromArgb(255,180,180):Color.White,11,true);state.Regions.Add(new(r,a,"action"));x+=w;}var more=new Rectangle(x,y,62,h);e.Display.Draw2dRectangle(more,Color.FromArgb(40,255,255,255),1,Color.Transparent);DrawText(e,"⋯ Mehr",x+8,y+12,Color.White,11,true);state.Regions.Add(new(more,null,"more"));if(state.HoverIndex>=0&&state.HoverIndex<actions.Count&&(DateTime.UtcNow-state.HoverSince).TotalMilliseconds>=settings.TooltipDelay)DrawTooltip(e,actions[state.HoverIndex],state.Regions[state.HoverIndex].Bounds,size.Width,size.Height);}
 int PositionX(int width,List<ContextAction>a){int estimated=Measure(state.Context.Caption)+36+a.Sum(x=>Measure(x.Label)+34)+66;return settings.Corner switch{HudCorner.TopLeft or HudCorner.BottomLeft=>settings.Margin,HudCorner.TopRight or HudCorner.BottomRight=>Math.Max(settings.Margin,width-estimated-settings.Margin),_=>state.Context.Anchor.IsValid&&state.Context.Anchor.X<0?Math.Max(settings.Margin,width-estimated-settings.Margin):settings.Margin};}int PositionY(int height)=>settings.Corner is HudCorner.BottomLeft or HudCorner.BottomRight?Math.Max(settings.Margin,height-38-settings.Margin):settings.Margin;
 void DrawTooltip(DrawEventArgs e,ContextAction a,Rectangle button,int vw,int vh){var eng=a.Macro.Trim().Split(' ')[0].TrimStart('_','-','!');var w=310;var h=84;var x=Math.Min(button.Left,vw-w-30);var y=button.Bottom+8;if(y+h>vh-30)y=button.Top-h-8;var r=new Rectangle(x,y,w,h);e.Display.Draw2dRectangle(r,Color.FromArgb(100,255,255,255),1,Color.FromArgb(245,30,30,30));DrawText(e,$"{a.Icon} {a.Label}",x+10,y+12,Color.White,12,true);DrawText(e,a.Hint,x+10,y+34,Color.LightGray,10,false);DrawText(e,$"Englischer Befehl: {eng}",x+10,y+56,Color.Gray,9,false);}
 static int Measure(string s)=>Math.Max(35,s.Length*7);static string Icon(SelectionKind k)=>k switch{SelectionKind.Block=>"◆",SelectionKind.Mesh or SelectionKind.MeshFace=>"△",SelectionKind.Curve or SelectionKind.ClosedPlanarCurve=>"⌁",SelectionKind.SubD or SelectionKind.SubDFace=>"◇",_=>"⬒"};static void DrawText(DrawEventArgs e,string t,int x,int y,Color c,int h,bool b)=>e.Display.Draw2dText(t,c,new Point2d(x,y),false,h,"Segoe UI");
}
